package app.aware.core.protocol.time

import app.aware.core.protocol.testing.SpecFiles
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

class TimeZoneDenylistTest {
    /** PLAT-HOOK-015 patterns plus the PLAT-ANDROID-030 platform patterns. */
    private val patterns = listOf(
        Regex("""\b(Africa|America|Antarctica|Arctic|Asia|Atlantic|Australia|Europe|Indian|Pacific|Etc)/[A-Za-z_+-]+"""),
        Regex("""\b(UTC|GMT)\s*[+-]\s*[0-9]"""),
        Regex("""["'`][+-](0[0-9]|1[0-4]):?[0-5][0-9]["'`]"""),
        Regex("""["'`](BRT|JST|PST|PDT|EST|EDT|CST|CDT|MST|MDT|CET|CEST|EET|BST|IST)["'`]"""),
        Regex("""\bTZ\s*="""),
        Regex("""user\.timezone"""),
        Regex("""ZoneId\.of\("""),
        Regex("""ZoneId\.SHORT_IDS"""),
        Regex("""ZoneOffset\.of(Hours|HoursMinutes|HoursMinutesSeconds)?\("""),
        Regex("""TimeZone\.getTimeZone\("""),
        Regex("""TimeZone\.setDefault\("""),
    )

    private fun productionFiles(root: File): List<File> = root.walkTopDown()
        .onEnter { dir -> dir == root || (dir.name != "build" && !dir.name.startsWith(".")) }
        .filter { it.isFile }
        .filter { file ->
            val path = file.relativeTo(root).invariantSeparatorsPath
            path.contains("/src/main/") ||
                file.name == "build.gradle.kts" ||
                path == "settings.gradle.kts" ||
                path == "gradle.properties" ||
                path == "gradle/libs.versions.toml"
        }
        .toList()

    private fun hits(file: File, root: File): List<String> {
        val found = mutableListOf<String>()
        file.readLines(Charsets.UTF_8).forEachIndexed { index, line ->
            for (pattern in patterns) {
                if (pattern.containsMatchIn(line)) {
                    found += "${file.relativeTo(root).invariantSeparatorsPath}:${index + 1}: ${pattern.pattern}"
                }
            }
        }
        return found
    }

    @Test
    fun `CORE-TIME-003 PLAT-HOOK-015 PLAT-ANDROID-030 production sources and build files hold no zone or offset literal`() {
        val root = SpecFiles.clientRoot()
        val files = productionFiles(root)
        assertTrue("no production files found under $root", files.any { it.path.contains("src") })
        assertTrue(files.any { it.name == "build.gradle.kts" })
        val found = files.flatMap { hits(it, root) }
        assertTrue("time zone literals found:\n" + found.joinToString("\n"), found.isEmpty())
    }

    @Test
    fun `CORE-TIME-003 PLAT-HOOK-015 the patterns catch the forbidden forms and allow UTC`() {
        val forbidden = listOf(
            "val z = \"America/Sao_Paulo\"",
            "UTC-3",
            "GMT+9",
            "\"+09:00\"",
            "'-0300'",
            "\"JST\"",
            "TZ=Asia/Tokyo",
            "-Duser.timezone=x",
            "ZoneId.of(\"x\")",
            "ZoneId.SHORT_IDS",
            "ZoneOffset.ofHours(3)",
            "ZoneOffset.of(\"x\")",
            "TimeZone.getTimeZone(\"x\")",
            "TimeZone.setDefault(null)",
        )
        for (line in forbidden) {
            assertTrue(line, patterns.any { it.containsMatchIn(line) })
        }
        val allowed = listOf("ZoneId.systemDefault()", "ZoneOffset.ofTotalSeconds(minutes * 60)", "ZoneOffset.UTC", "Instant.parse(text)", "\"Z\"")
        for (line in allowed) {
            assertTrue(line, patterns.none { it.containsMatchIn(line) })
        }
    }
}
